DROP PROCEDURE IF EXISTS `SP_ACCION_ULTIMO_PRECIO_REFRESH`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACCION_ULTIMO_PRECIO_REFRESH` ()   BEGIN

UPDATE Inversion I
INNER JOIN instrumento Ins
    ON I.id_instrumento = Ins.id_instrumento
SET 
    I.id_estado_inversion = 131,
    I.fecha_actualizacion = NOW()
WHERE 
    I.id_estado_inversion = 128
    AND Ins.fecha_vencimiento < CURDATE();
    

        id_catalogo_valor,
        id_catalogo,
        codigo,
        nombre,
        descripcion,
        orden_visual,
        activo,
        fecha_creacion,
        fecha_actualizacion
    )
    SELECT
        S.SHA_ISSUER_ID AS id_catalogo_valor,
        3 AS id_catalogo,
        LEFT(UPPER(S.SHA_ISSUER), 10) AS codigo,
        S.SHA_ISSUER AS nombre,
        S.SHA_ISSUER AS descripcion,
        1 AS orden_visual,
        1 AS activo,
        NOW() AS fecha_creacion,
        NOW() AS fecha_actualizacion
    FROM
    (
        SELECT
            SHA_ISSUER_ID,
            MAX(SHA_ISSUER) AS SHA_ISSUER
        FROM inversion.shares
        WHERE SHA_ISSUER_ID IS NOT NULL
          AND SHA_ISSUER IS NOT NULL
          AND SHA_TYPE = 'ACCIONES'
          AND SHA_PRICE > 0
          AND SHA_NUMBER > 0
          AND SHA_CASH_VALUE > 0
        GROUP BY SHA_ISSUER_ID
    ) S
    LEFT JOIN sipro_desa.catalogo_valor C
        ON C.id_catalogo_valor = S.SHA_ISSUER_ID
       AND C.id_catalogo = 3
    WHERE C.id_catalogo_valor IS NULL;


    

        id_emisor,
        emisor,
        fecha_ultimo_precio,
        precio_ultimo,
        precio_minimo_dia,
        precio_maximo_dia,
        volumen_ultimo_dia,
        valor_ultimo_dia,
        transacciones_ultimo_dia,
        precio_minimo_30d,
        precio_maximo_30d,
        precio_promedio_30d,
        dias_sin_negociacion
    )
    SELECT
        M.id_emisor AS id_emisor,
        S.SHA_ISSUER AS emisor,
        S.SHA_DATE AS fecha_ultimo_precio,

        ROUND(SUM(S.SHA_CASH_VALUE) / NULLIF(SUM(S.SHA_NUMBER), 0), 6) AS precio_ultimo,
        ROUND(MIN(S.SHA_PRICE), 6) AS precio_minimo_dia,
        ROUND(MAX(S.SHA_PRICE), 6) AS precio_maximo_dia,

        SUM(S.SHA_NUMBER) AS volumen_ultimo_dia,
        ROUND(SUM(S.SHA_CASH_VALUE), 2) AS valor_ultimo_dia,
        COUNT(*) AS transacciones_ultimo_dia,

        NULL AS precio_minimo_30d,
        NULL AS precio_maximo_30d,
        NULL AS precio_promedio_30d,

        DATEDIFF(CURDATE(), S.SHA_DATE) AS dias_sin_negociacion

    FROM inversion.shares S
    INNER JOIN sipro_desa.map_emisor_legacy M
        ON M.id_emisor_legacy = S.SHA_ISSUER_ID
    INNER JOIN
    (
        SELECT
            SHA_ISSUER_ID,
            MAX(SHA_DATE) AS fecha_ultimo_precio
        FROM inversion.shares
        WHERE SHA_TYPE = 'ACCIONES'
          AND SHA_PRICE > 0
          AND SHA_NUMBER > 0
          AND SHA_CASH_VALUE > 0
        GROUP BY SHA_ISSUER_ID
    ) U
        ON U.SHA_ISSUER_ID = S.SHA_ISSUER_ID
       AND U.fecha_ultimo_precio = S.SHA_DATE

    WHERE S.SHA_TYPE = 'ACCIONES'
      AND S.SHA_PRICE > 0
      AND S.SHA_NUMBER > 0
      AND S.SHA_CASH_VALUE > 0

    GROUP BY
        M.id_emisor,
        S.SHA_ISSUER,
        S.SHA_DATE
    ON DUPLICATE KEY UPDATE
        emisor = VALUES(emisor),
        fecha_ultimo_precio = VALUES(fecha_ultimo_precio),
        precio_ultimo = VALUES(precio_ultimo),
        precio_minimo_dia = VALUES(precio_minimo_dia),
        precio_maximo_dia = VALUES(precio_maximo_dia),
        volumen_ultimo_dia = VALUES(volumen_ultimo_dia),
        valor_ultimo_dia = VALUES(valor_ultimo_dia),
        transacciones_ultimo_dia = VALUES(transacciones_ultimo_dia),
        precio_minimo_30d = VALUES(precio_minimo_30d),
        precio_maximo_30d = VALUES(precio_maximo_30d),
        precio_promedio_30d = VALUES(precio_promedio_30d),
        dias_sin_negociacion = VALUES(dias_sin_negociacion);


    

    UPDATE sipro_desa.accion_ultimo_precio A
    LEFT JOIN
    (
        SELECT
            M.id_emisor,
            ROUND(SUM(P.SHA_CASH_VALUE) / NULLIF(SUM(P.SHA_NUMBER), 0), 6) AS precio_anterior
        FROM inversion.shares P
        INNER JOIN sipro_desa.map_emisor_legacy M
            ON M.id_emisor_legacy = P.SHA_ISSUER_ID
        INNER JOIN
        (
            SELECT
                M2.id_emisor_legacy,
                MAX(X.SHA_DATE) AS fecha_anterior
            FROM inversion.shares X
            INNER JOIN sipro_desa.map_emisor_legacy M2
                ON M2.id_emisor_legacy = X.SHA_ISSUER_ID
            INNER JOIN sipro_desa.accion_ultimo_precio A2
                ON A2.id_emisor = M2.id_emisor
            WHERE X.SHA_TYPE = 'ACCIONES'
              AND X.SHA_PRICE > 0
              AND X.SHA_NUMBER > 0
              AND X.SHA_CASH_VALUE > 0
              AND X.SHA_DATE < A2.fecha_ultimo_precio
            GROUP BY M2.id_emisor_legacy
        ) UA
            ON UA.id_emisor_legacy = P.SHA_ISSUER_ID
           AND UA.fecha_anterior = P.SHA_DATE
        WHERE P.SHA_TYPE = 'ACCIONES'
          AND P.SHA_PRICE > 0
          AND P.SHA_NUMBER > 0
          AND P.SHA_CASH_VALUE > 0
        GROUP BY M.id_emisor
    ) B
        ON B.id_emisor = A.id_emisor
    SET
        A.precio_anterior = B.precio_anterior,
        A.variacion_precio =
            CASE
                WHEN B.precio_anterior IS NULL THEN NULL
                ELSE ROUND(A.precio_ultimo - B.precio_anterior, 6)
            END,
        A.variacion_porcentaje =
            CASE
                WHEN B.precio_anterior IS NULL OR B.precio_anterior = 0 THEN NULL
                ELSE ROUND(((A.precio_ultimo - B.precio_anterior) / B.precio_anterior) * 100, 6)
            END;


    

    UPDATE sipro_desa.accion_ultimo_precio A
    LEFT JOIN
    (
        SELECT
            D.id_emisor,
            ROUND(MIN(D.precio_diario), 6) AS precio_minimo_30d,
            ROUND(MAX(D.precio_diario), 6) AS precio_maximo_30d,
            ROUND(AVG(D.precio_diario), 6) AS precio_promedio_30d
        FROM
        (
            SELECT
                M.id_emisor,
                S2.SHA_DATE,
                SUM(S2.SHA_CASH_VALUE) / NULLIF(SUM(S2.SHA_NUMBER), 0) AS precio_diario
            FROM inversion.shares S2
            INNER JOIN sipro_desa.map_emisor_legacy M
                ON M.id_emisor_legacy = S2.SHA_ISSUER_ID
            INNER JOIN sipro_desa.accion_ultimo_precio A3
                ON A3.id_emisor = M.id_emisor
            WHERE S2.SHA_TYPE = 'ACCIONES'
              AND S2.SHA_PRICE > 0
              AND S2.SHA_NUMBER > 0
              AND S2.SHA_CASH_VALUE > 0
              AND S2.SHA_DATE BETWEEN DATE_SUB(A3.fecha_ultimo_precio, INTERVAL 30 DAY)
                                  AND A3.fecha_ultimo_precio
            GROUP BY
                M.id_emisor,
                S2.SHA_DATE
        ) D
        GROUP BY D.id_emisor
    ) R
        ON R.id_emisor = A.id_emisor
    SET
        A.precio_minimo_30d = R.precio_minimo_30d,
        A.precio_maximo_30d = R.precio_maximo_30d,
        A.precio_promedio_30d = R.precio_promedio_30d;

    
    
    CALL sp_actualizar_snapshot_cartera();

    
    SELECT CAST(descripcion AS UNSIGNED) INTO @v_retention
      FROM catalogo_valor
      WHERE id_catalogo = 19
        AND codigo = 'RETENTION_DAYS'
      LIMIT 1;

    DELETE FROM snapshot_cartera_diaria
    WHERE fecha < CURDATE() - INTERVAL IFNULL(@v_retention, 1825) DAY;

END$$

DROP PROCEDURE IF EXISTS `SP_ACTUALIZAR_AMORTIZACION_INVERSION`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACTUALIZAR_AMORTIZACION_INVERSION` (IN `p_fecha_corte` DATE, IN `p_nuevo_estado_cuota` INT)   BEGIN
    /*
      ========================================================================================
      PROCEDIMIENTO ALMACENADO: SP_ACTUALIZAR_AMORTIZACION_INVERSION
      PROYECTO: SIPRO_07
      
      DESCRIPCIÓN:
      Actualiza el estado de las amortizaciones/cuotas vencidas y el estado de las inversiones
      cuya fecha de vencimiento (en tabla instrumento) haya transcurrido sin registrarse ventas anticipadas.
      
      PARÁMETROS:
      - p_fecha_corte: Fecha límite para evaluar vencimiento (Si es NULL se usa CURDATE()).
      - p_nuevo_estado_cuota: ID de catálogo para cuotas vencidas (Ej: 135=Pagada, 136=Morosa). 
                              Si es NULL por defecto asigna 135 (Pagada).
                              
      CATÁLOGOS RELEVANTES (catalogo_valor):
      - Estado Amortización (id_catalogo = 5):
          134 = Pendiente de pago
          135 = Pagada
          136 = Morosa
          137 = Anulada
          200 = AnuladaVentParcial
          227 = Venta Anticipada
      - Estado Inversión (id_catalogo = 4):
          128 = Activa / Vigente
          129 = Finalizada / Pagada
          130 = Vendida
          131 = Anulada

      EJEMPLOS DE USO:
      1. Ejecución estándar (usa la fecha actual y marca cuotas vencidas como 135-Pagada)
         CALL SP_ACTUALIZAR_AMORTIZACION_INVERSION(NULL, NULL);
      2. Ejecución a una fecha de corte específica (ej. 31-Julio-2026)
         CALL SP_ACTUALIZAR_AMORTIZACION_INVERSION('2026-07-31', 135);
      3. Ejecución para marcar cuotas vencidas como 136-Morosa
         CALL SP_ACTUALIZAR_AMORTIZACION_INVERSION(CURDATE(), 136);
      ========================================================================================
    */

    -- Manejo de valores por defecto si se envían nulos
    IF p_fecha_corte IS NULL THEN
        SET p_fecha_corte = CURDATE();
    END IF;

    IF p_nuevo_estado_cuota IS NULL THEN
        SET p_nuevo_estado_cuota = 135; -- Por defecto: 135 (Pagada)
    END IF;

    -- ========================================================================================
    -- PASO 1: Actualizar cuotas pendientes (134) cuya fecha de pago sea menor o igual a p_fecha_corte
    -- ========================================================================================
    UPDATE amortizacion A
    INNER JOIN inversion I ON A.id_inversion = I.id_inversion
    SET A.id_estado_amortizacion = p_nuevo_estado_cuota,
        A.fecha_actualizacion = NOW()
    WHERE A.fecha_pago <= p_fecha_corte
      AND A.id_estado_amortizacion = 134 -- Solo cuotas Pendientes de pago
      AND A.eliminado = 0
      AND I.fecha_venta IS NULL        -- Solo inversiones no vendidas
      AND I.id_estado_inversion = 128  -- Solo inversiones activas
      AND I.eliminado = 0;

    -- ========================================================================================
    -- PASO 2: Actualizar inversiones activas (128) cuya fecha de vencimiento (en instrumento)
    --         expiró a Finalizada (129)
    -- ========================================================================================
    UPDATE inversion I
    INNER JOIN instrumento inst ON I.id_instrumento = inst.id_instrumento
    SET I.id_estado_inversion = 129,   -- 129 = Finalizada / Pagada
        I.fecha_actualizacion = NOW()
    WHERE inst.fecha_vencimiento <= p_fecha_corte
      AND I.id_estado_inversion = 128  -- Solo inversiones activas
      AND I.fecha_venta IS NULL        -- Solo inversiones no vendidas
      AND I.eliminado = 0
      -- Asegurar que no le queden cuotas pendientes de cobro
      AND NOT EXISTS (
          SELECT 1 
          FROM amortizacion subA 
          WHERE subA.id_inversion = I.id_inversion 
            AND subA.id_estado_amortizacion = 134 
            AND subA.eliminado = 0
      );

END$$

DROP PROCEDURE IF EXISTS `SP_ACTUALIZAR_AMORTIZACION_MENSUAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ACTUALIZAR_AMORTIZACION_MENSUAL` (IN `_FechaInicial` DATE, IN `_FechaFinal` DATE)   BEGIN
/*
UPDATE amortizacion set activo=1
where id_inversion IN (
select I.id_inversion from amortizacion A, inversion I where fecha_pago between _FechaInicial and _FechaFinal
and A.id_inversion = I.id_inversion
and A.eliminado = 0
and I.eliminado = 0
and I.fecha_venta is null
)
and fecha_pago between _FechaInicial and _FechaFinal;
*/
END$$

DROP PROCEDURE IF EXISTS `sp_actualizar_snapshot_cartera`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_snapshot_cartera` ()   BEGIN
    DECLARE v_unreal_up   DECIMAL(6,2);
    DECLARE v_unreal_down DECIMAL(6,2);
    DECLARE v_daily_up    DECIMAL(6,2);
    DECLARE v_daily_down  DECIMAL(6,2);
    DECLARE v_vr_thr      DECIMAL(6,2);
    DECLARE v_rsi_up      INT;
    DECLARE v_rsi_down    INT;
    DECLARE v_days_no_tr  INT;

    SELECT CAST(descripcion AS DECIMAL(6,2)) INTO v_unreal_up   FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'UNREALIZED_PCT_UP' LIMIT 1;
    SELECT CAST(descripcion AS DECIMAL(6,2)) INTO v_unreal_down FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'UNREALIZED_PCT_DOWN' LIMIT 1;
    SELECT CAST(descripcion AS DECIMAL(6,2)) INTO v_daily_up    FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'DAILY_VARIATION_UP' LIMIT 1;
    SELECT CAST(descripcion AS DECIMAL(6,2)) INTO v_daily_down  FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'DAILY_VARIATION_DOWN' LIMIT 1;
    SELECT CAST(descripcion AS DECIMAL(6,2)) INTO v_vr_thr      FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'VOLUME_RELATIVE' LIMIT 1;
    SELECT CAST(descripcion AS UNSIGNED)     INTO v_rsi_up      FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'RSI_OVERBOUGHT' LIMIT 1;
    SELECT CAST(descripcion AS UNSIGNED)     INTO v_rsi_down    FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'RSI_OVERSOLD' LIMIT 1;
    SELECT CAST(descripcion AS UNSIGNED)     INTO v_days_no_tr  FROM catalogo_valor WHERE id_catalogo = 19 AND codigo = 'DAYS_NO_TRADE' LIMIT 1;

    DELETE FROM snapshot_cartera_diaria WHERE fecha = CURDATE();

        id_emisor,
        fecha,
        cantidad_posicion,
        costo_promedio,
        precio_mercado,
        valor_mercado,
        pl_no_realizado,
        porcentaje_no_realizado,
        sma_5,
        sma_20,
        vr,
        dias_sin_negociacion,
        alertas
    )
    WITH daily_prices AS (
        SELECT 
            m.id_emisor, 
            s.SHA_DATE, 
            AVG(CAST(s.SHA_PRICE AS DECIMAL(18,6))) AS daily_avg_price,
            SUM(s.SHA_NUMBER) AS daily_volume,
            ROW_NUMBER() OVER(PARTITION BY m.id_emisor ORDER BY s.SHA_DATE DESC) as rn
        FROM inversion.shares s
        INNER JOIN sipro_desa.map_emisor_legacy m ON s.SHA_ISSUER_ID = m.id_emisor_legacy
        GROUP BY m.id_emisor, s.SHA_DATE
    ),
    sma_data AS (
        SELECT 
            id_emisor,
            TRUNCATE(AVG(CASE WHEN rn <= 5 THEN daily_avg_price END), 6) AS sma_5,
            TRUNCATE(AVG(CASE WHEN rn <= 20 THEN daily_avg_price END), 6) AS sma_20,
            TRUNCATE(AVG(CASE WHEN rn <= 30 THEN daily_volume END), 6) AS avg_vol_30
        FROM daily_prices
        WHERE rn <= 30
        GROUP BY id_emisor
    )
    SELECT
        i.id_emisor,
        CURDATE() AS fecha,
        TRUNCATE(SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad
                 WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END), 6) AS cantidad_posicion,
        CASE WHEN SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad END) = 0 THEN NULL
             ELSE TRUNCATE(
                 SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) /
                 SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad END)
                ,6) END AS costo_promedio,
        ap.precio_ultimo AS precio_mercado,
        TRUNCATE((SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad
                 WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0)), 6) AS valor_mercado,
        TRUNCATE(( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad
                    WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0))
          - SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) ), 6) AS pl_no_realizado,
        CASE WHEN SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.cantidad * ao.precio_unitario END) = 0 THEN NULL
             ELSE TRUNCATE(
                 ( ( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad
                                WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0))
                    - SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) )
                   / SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.cantidad * ao.precio_unitario END) ) * 100,2) END AS porcentaje_no_realizado,
        sma.sma_5,
        sma.sma_20,
        TRUNCATE(ap.volumen_ultimo_dia / NULLIF(sma.avg_vol_30, 0), 2) AS vr,
        ap.dias_sin_negociacion,
        CONCAT('[',
            CONCAT_WS(',',
                CASE WHEN 
                    ( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0))
                    - SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) ) IS NOT NULL 
                    AND 
                    ( CASE WHEN SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario END) = 0 THEN NULL ELSE ROUND( ( ( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0)) - SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) ) / SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario END) ) * 100,2) END ) > v_unreal_up   
                    THEN CONCAT('"', 'No Realizado > ', v_unreal_up, '%', '"') ELSE NULL END,
                CASE WHEN 
                    ( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0))
                    - SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) ) IS NOT NULL 
                    AND 
                    ( CASE WHEN SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario END) = 0 THEN NULL ELSE ROUND( ( ( (SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) * IFNULL(ap.precio_ultimo,0)) - SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario ELSE 0 END) ) / SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad * ao.precio_unitario END) ) * 100,2) END ) < v_unreal_down 
                    THEN CONCAT('"', 'No Realizado < ', v_unreal_down, '%', '"') ELSE NULL END,
                CASE WHEN ap.variacion_porcentaje IS NOT NULL AND ap.variacion_porcentaje > v_daily_up   THEN CONCAT('"', 'Variacion diaria > ', v_daily_up, '%', '"') ELSE NULL END,
                CASE WHEN ap.variacion_porcentaje IS NOT NULL AND ap.variacion_porcentaje < v_daily_down THEN CONCAT('"', 'Variacion diaria < ', v_daily_down, '%', '"') ELSE NULL END,
                CASE WHEN (ap.volumen_ultimo_dia / NULLIF(sma.avg_vol_30, 0)) IS NOT NULL AND (ap.volumen_ultimo_dia / NULLIF(sma.avg_vol_30, 0)) > v_vr_thr THEN CONCAT('"', 'VR > ', v_vr_thr, '"') ELSE NULL END,
                CASE WHEN ap.dias_sin_negociacion IS NOT NULL AND ap.dias_sin_negociacion > v_days_no_tr THEN CONCAT('"', 'Sin negociacion > ', v_days_no_tr, ' dias', '"') ELSE NULL END
            ),
        ']') AS alertas
    FROM accion_operacion ao
    INNER JOIN instrumento i ON i.id_instrumento = ao.id_instrumento
    LEFT JOIN accion_ultimo_precio ap ON ap.id_emisor = i.id_emisor
    LEFT JOIN sma_data sma ON sma.id_emisor = i.id_emisor
    WHERE ao.activo = 1 AND ao.eliminado = 0 AND i.id_tipo_inversion IN (203,73)
    GROUP BY i.id_emisor;
END$$

DROP PROCEDURE IF EXISTS `SP_FLUJO_CAPITAL_CONSOLIDADO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_FLUJO_CAPITAL_CONSOLIDADO` (IN `_initialDate` DATE, IN `_finalDate` DATE, IN `_id_grupo_familiar` INT, IN `_id_propietario` INT)   BEGIN
 -- Consulta principal: Flujo de capital consolidado por fecha, propietario y empresa
    SELECT
        a.fecha_pago AS fecha,
        CONCAT(p.nombres, ' ', p.apellidos) AS propietario,
        e.nombre AS empresa,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.interes ELSE 0 END) AS interes,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.capital ELSE 0 END) AS capital,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.descuento ELSE 0 END) AS descuento,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.interes ELSE 0 END) AS interes_moroso,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.descuento ELSE 0 END) AS descuento_moroso,
        SUM(a.interes + a.capital) AS total,
        e.id_emisor,
        i.id_propietario
    FROM amortizacion a
    INNER JOIN inversion i ON a.id_inversion = i.id_inversion
    INNER JOIN persona p ON i.id_propietario = p.id_persona
    INNER JOIN instrumento inst ON i.id_instrumento = inst.id_instrumento
    INNER JOIN emisor e ON inst.id_emisor = e.id_emisor
    WHERE a.fecha_pago BETWEEN _initialDate AND _finalDate
        AND i.id_estado_inversion = 128
        AND i.eliminado = 0
        AND a.id_estado_amortizacion IN (134, 135, 136)
        AND a.eliminado = 0
        AND (_id_grupo_familiar IS NULL OR i.id_grupo_familiar = _id_grupo_familiar)
        AND (_id_propietario IS NULL OR i.id_propietario = _id_propietario)
     GROUP BY a.fecha_pago, p.nombres, p.apellidos, e.nombre, e.id_emisor, i.id_propietario
/*
    UNION

    -- Fila de totales generales
    SELECT
        'X' AS fecha,
        '' AS propietario,
        'TOTAL' AS empresa,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.interes ELSE 0 END) AS interes,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.capital ELSE 0 END) AS capital,
        SUM(CASE WHEN a.id_estado_amortizacion IN (134, 135) THEN a.descuento ELSE 0 END) AS descuento,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.interes ELSE 0 END) AS interes_moroso,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.capital ELSE 0 END) AS capital_moroso,
        SUM(CASE WHEN a.id_estado_amortizacion = 136 THEN a.descuento ELSE 0 END) AS descuento_moroso,
        SUM(a.interes) + SUM(a.capital) AS total,
        e.id_emisor,
        i.id_propietario
    FROM amortizacion a
    INNER JOIN inversion i ON a.id_inversion = i.id_inversion
    WHERE a.fecha_pago BETWEEN _initialDate AND _finalDate
        AND i.id_estado_inversion = 128
        AND i.eliminado = 0
        AND a.id_estado_amortizacion IN (134, 135, 136)
        AND a.eliminado = 0
        AND (_id_grupo_familiar IS NULL OR i.id_grupo_familiar = _id_grupo_familiar)
        AND (_id_propietario IS NULL OR i.id_propietario = _id_propietario)
*/
    ORDER BY fecha, propietario;
END$$

DROP PROCEDURE IF EXISTS `SP_IMPORTAR_INVERSION_AMORTIZACION`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_IMPORTAR_INVERSION_AMORTIZACION` (IN `_fecha_compra` DATE)   BEGIN

drop table inversion_backup_migracion;
CREATE TABLE IF NOT EXISTS `inversion_backup_migracion` AS 
SELECT * FROM `inversion`;

update inversion.inversion
set inv_instrumento = 'SRI 2034-12-31',
    id_instrumento = 222
where inv_emisor = 'SRI 2034-12-31';




    id_inversion,                    
    id_grupo_familiar,               
    id_instrumento,                  
    id_propietario,                  
    id_aportante,                     
    liquidacion,                      
    id_estado_inversion,              
    fecha_compra,                     
    fecha_venta,                      
    valor_nominal,                    
    monto_a_negociar,                 
    capital_invertido,                
    tasa_interes,                     
    rendimiento_nominal,             
    rendimiento_efectivo,             
    valor_efectivo,                   
    valor_sin_comision,               
    valor_con_interes,                
    interes_acumulado_previo,         
    interes_mensual,                  
    interes_primer_mes,              
    total_comisiones,                 
    tasa_mensual_real,                
    fecha_primer_pago,                
    precio_compra,                    
    precio_neto_compra,               
    comision_bolsa,                   
    comision_casa_valores,            
    retencion_fuente,                 
    observacion,                      
    eliminado,                        
    fecha_creacion,                   
    fecha_actualizacion               
)
SELECT 
    id as id_inversion,
    1 as id_grupo_familiar,  
    id_instrumento,  
    CASE inv_propietario
        WHEN 'Jhon' THEN 1
        WHEN 'Cristian' THEN 2
        WHEN 'Isabel' THEN 3
        WHEN 'Jaime' THEN 4
        WHEN 'Argentina' THEN 5
        ELSE 1  
    END as id_propietario,
    1 as id_aportante,  
    inv_liquidacion as liquidacion,
    CASE is_active
        WHEN 1 THEN 128  
        WHEN 0 THEN 132  
        ELSE 128  
    END as id_estado_inversion,
    inv_fecha_compra as fecha_compra,
    inv_fecha_venta as fecha_venta,
    inv_valor_nominal as valor_nominal,
    inv_monto_a_negociar as monto_a_negociar,
    inv_capital_invertido as capital_invertido,
    inv_tasa_interes as tasa_interes,
    inv_rendimiento_nominal as rendimiento_nominal,
    inv_rendimiento_efectivo as rendimiento_efectivo,
    inv_valor_efectivo as valor_efectivo,
    inv_valor_sin_comision as valor_sin_comision,
    inv_valor_con_interes as valor_con_interes,
    inv_interes_acumulado_previo as interes_acumulado_previo,
    inv_valor_interes as interes_mensual,
    inv_interes_primer_mes as interes_primer_mes,
    inv_total_comisiones as total_comisiones,
    inv_tasa_mensual_real as tasa_mensual_real,
    inv_fecha_primer_pago as fecha_primer_pago,
    inv_precio_comprado as precio_compra,
    inv_precio_neto_comprado as precio_neto_compra,
    inv_comision_bolsa as comision_bolsa,
    inv_comision_operador as comision_casa_valores,
    inv_retencion as retencion_fuente,
    NULL as observacion,  
    is_deleted as eliminado,
    created_at as fecha_creacion,
    updated_at as fecha_actualizacion
FROM `inversion`.`inversion`
where inv_fecha_compra = _fecha_compra;


SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE `amortizacion`;
SET FOREIGN_KEY_CHECKS = 1;


    id_amortizacion,
    id_inversion,
    numero_cuota,           
    fecha_pago,
    interes,
    capital,
    descuento,
    total,
    int_parcial,            
    retencion,
    id_estado_amortizacion, 
    pagada,                 
    activo,                 
    eliminado,              
    fecha_creacion,         
    fecha_actualizacion     
)
SELECT 
    A.id as id_amortizacion,
    inv_id as id_inversion,
    NULL as numero_cuota,   
    am_fecha_pago as fecha_pago,
    am_interes as interes,
    am_capital as capital,
    am_descuento as descuento,
    am_total as total,
    am_int_parcial as int_parcial,  
    am_retencion as retencion,
    CASE 
        WHEN A.is_deleted = 1 THEN 137  
        WHEN am_pagada = 1 THEN 135   
        WHEN am_pagada = 2 THEN 136   
        WHEN am_pagada = 0 AND A.is_active = 1 THEN 134  
        ELSE 134  
    END as id_estado_amortizacion,
    am_pagada as pagada,
    A.is_active as activo,
    A.is_deleted as eliminado,
    NOW() as fecha_creacion,
    NOW() as fecha_actualizacion
FROM `inversion`.`amortizacion` A, `inversion`.`inversion` I 
where 
      I.id = A.inv_id

;


END$$

DROP PROCEDURE IF EXISTS `SP_PATRIMONIO_CONSOLIDADO`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_PATRIMONIO_CONSOLIDADO` (IN `p_fecha_inicio` VARCHAR(10), IN `p_fecha_fin` VARCHAR(10), IN `p_id_grupo_familiar` INT, IN `p_id_propietario` INT, IN `p_incluir_dividendos` TINYINT(1), IN `p_incluir_plusvalia` TINYINT(1))   BEGIN
    -- Crear tabla temporal para almacenar resultados intermedios sin re-evaluar subconsultas
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_patrimonio_resultado (
        id INT AUTO_INCREMENT PRIMARY KEY,
        detalle VARCHAR(100),
        valor DECIMAL(18, 2)
    ) ENGINE=InnoDB;

    -- Limpiar la tabla por si fue creada previamente en la misma sesión
    TRUNCATE TABLE temp_patrimonio_resultado;

    -- Llenar la tabla temporal con los 12 rubros
    -- 1. Intereses esperados (RANGO DE FECHAS PROYECTADO: p_fecha_inicio a p_fecha_fin)
    SELECT 'Intereses esperados' as detalle,
           COALESCE(SUM(A.interes), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND A.fecha_pago <= p_fecha_fin
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)

    UNION ALL

    -- 2. Capital bonos (Capital Invertido Original a Costo)
    SELECT 'Capital bonos' as detalle,
           COALESCE(SUM(I.capital_invertido), 0) as valor
    FROM inversion I
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE I.id_estado_inversion = 128
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 4
      AND INS.fecha_vencimiento > p_fecha_inicio
      AND I.fecha_venta IS NULL

    UNION ALL

    -- 3. Bonos vencimiento próximo (Capital a 12 meses desde fecha_inicio)
    SELECT 'Bonos vencimiento próximo' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND A.fecha_pago <= DATE_ADD(STR_TO_DATE(p_fecha_inicio, '%Y-%m-%d'), INTERVAL 1 YEAR)
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 4

    UNION ALL

    -- 4. Obligaciones
    SELECT 'Obligaciones' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 5

    UNION ALL

    -- 5. Papeles Comerciales
    SELECT 'Papeles Comerciales' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 3

    UNION ALL

    -- 6. Notas Crédito
    SELECT 'Notas Crédito' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 91

    UNION ALL

    -- 7. Acciones Pago Interes
    SELECT 'Acciones Pago Interes' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 73

    UNION ALL

    -- 8. Acciones Sin Interés
    SELECT 'Acciones Sin Interés' as detalle,
           COALESCE(SUM(
               CASE
                   WHEN ao.id_tipo_operacion IN (204, 232) THEN ao.valor_neto
                   WHEN ao.id_tipo_operacion IN (205) THEN -ao.valor_neto
                   ELSE 0
               END
           ), 0) as valor
    FROM sipro_desa.accion_operacion ao
    WHERE ao.activo = 1
      AND ao.eliminado = 0
      AND (p_id_propietario IS NULL OR ao.id_persona = p_id_propietario)
      AND (p_id_grupo_familiar IS NULL OR ao.id_persona IN (
          SELECT gfp.id_persona 
          FROM sipro_desa.grupo_familiar_persona gfp 
          WHERE gfp.id_grupo_familiar = p_id_grupo_familiar
      ))

    UNION ALL

    -- 9. Dividendos en Acciones
    SELECT 'Dividendos en Acciones' as detalle,
           COALESCE(SUM(ao.valor_neto), 0) as valor
    FROM sipro_desa.accion_operacion ao
    WHERE ao.activo = 1
      AND ao.eliminado = 0
      AND p_incluir_dividendos = 1
      AND ao.id_tipo_operacion IN (206, 207)
      AND (p_id_propietario IS NULL OR ao.id_persona = p_id_propietario)
      AND (p_id_grupo_familiar IS NULL OR ao.id_persona IN (
          SELECT gfp.id_persona 
          FROM sipro_desa.grupo_familiar_persona gfp 
          WHERE gfp.id_grupo_familiar = p_id_grupo_familiar
      ))

    UNION ALL

    -- 10. Plusvalía Acciones
    SELECT 'Plusvalía Acciones' as detalle,
           CASE 
               WHEN p_incluir_plusvalia = 1 THEN
                   COALESCE((
                       SELECT SUM(
                           (pe.cantidad_actual * IFNULL(aup.precio_ultimo, 0))
                           - pe.costo_desembolsado
                           - (CASE WHEN p_incluir_dividendos = 1 THEN pe.valor_dividendos_acciones ELSE 0 END)
                       )
                       FROM (
                           SELECT 
                               i.id_emisor,
                               SUM(CASE WHEN ao.id_tipo_operacion IN (204,206,207,212,232) THEN ao.cantidad WHEN ao.id_tipo_operacion IN (205,208) THEN -ao.cantidad ELSE 0 END) AS cantidad_actual,
                               SUM(CASE WHEN ao.id_tipo_operacion IN (204,232) THEN ao.valor_neto WHEN ao.id_tipo_operacion = 205 THEN -ao.valor_neto ELSE 0 END) AS costo_desembolsado,
                               SUM(CASE WHEN ao.id_tipo_operacion IN (206,207) THEN ao.valor_neto ELSE 0 END) AS valor_dividendos_acciones
                           FROM sipro_desa.accion_operacion ao
                           JOIN sipro_desa.instrumento i ON i.id_instrumento = ao.id_instrumento
                           WHERE ao.activo = 1 AND ao.eliminado = 0
                             AND (p_id_propietario IS NULL OR ao.id_persona = p_id_propietario)
                             AND (p_id_grupo_familiar IS NULL OR ao.id_persona IN (
                                 SELECT gfp.id_persona FROM sipro_desa.grupo_familiar_persona gfp WHERE gfp.id_grupo_familiar = p_id_grupo_familiar
                             ))
                           GROUP BY i.id_emisor
                           HAVING cantidad_actual > 0
                       ) pe
                       LEFT JOIN sipro_desa.accion_ultimo_precio aup ON aup.id_emisor = pe.id_emisor
                   ), 0)
               ELSE 0
           END as valor

    UNION ALL

    -- 11. Titularizaciones
    SELECT 'Titularizaciones' as detalle,
           COALESCE(SUM(A.capital), 0) as valor
    FROM amortizacion A
    JOIN inversion I ON A.id_inversion = I.id_inversion
    JOIN instrumento INS ON I.id_instrumento = INS.id_instrumento
    WHERE A.fecha_pago > p_fecha_inicio
      AND I.fecha_venta IS NULL
      AND A.id_estado_amortizacion IN (134, 135, 136)
      AND A.eliminado = 0
      AND I.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR I.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR I.id_propietario = p_id_propietario)
      AND INS.id_tipo_inversion = 75

    UNION ALL

    -- 12. Total Corriente
    SELECT 'Total Corriente' as detalle,
           COALESCE(SUM(ov.valor), 0) as valor
    FROM otro_valor ov
    WHERE ov.activo = 1
      AND ov.eliminado = 0
      AND (p_id_grupo_familiar IS NULL OR ov.id_grupo_familiar = p_id_grupo_familiar)
      AND (p_id_propietario IS NULL OR ov.id_propietario = p_id_propietario);

    -- RETORNAR TODOS LOS RUBROS MÁS EL TOTAL CALCULADO DIRECTAMENTE DE LA TABLA TEMPORAL
    SELECT detalle, valor FROM temp_patrimonio_resultado
    UNION ALL
    SELECT 'TOTAL' as detalle, COALESCE(SUM(valor), 0) as valor FROM temp_patrimonio_resultado;

    -- Eliminar la tabla temporal de la sesión
    DROP TEMPORARY TABLE IF EXISTS temp_patrimonio_resultado;
END$$

DROP PROCEDURE IF EXISTS `SP_RECUPERACION_ANUAL`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_RECUPERACION_ANUAL` (IN `_historico` INT)   BEGIN
   IF _historico = 0 THEN    -- SE BUSCA TODA LA INFORMACION PERO SOLO DE FECHAS FUTURAS
       SELECT CAST(YEAR(A.fecha_pago) AS CHAR) AS anio, 
              SUM(A.capital) AS capital, 
              SUM(A.interes) AS interes, 
              SUM(A.capital) + SUM(A.interes) AS total
       FROM amortizacion A, inversion I
       WHERE 
                   I.fecha_venta IS NULL
                   and A.id_estado_amortizacion IN (134, 135, 136)
		          and A.eliminado = 0
                  and I.eliminado = 0
                  and A.id_inversion = I.id_inversion
           AND A.fecha_pago > CURDATE()
       GROUP BY anio 
       ORDER BY anio ASC;
   ELSE   -- SE NECESITA SOLO EL INTERES PERO DE TODOS LOS AÑOS PREVIOS
   
       SELECT CAST(YEAR(A.fecha_pago) AS CHAR) AS anio, 
              SUM(A.capital) AS capital, 
              SUM(A.interes) AS interes, 
              SUM(A.capital) + SUM(A.interes) AS total
       FROM amortizacion A, inversion I
       WHERE 
		   A.eliminado = 0
           and I.eliminado = 0
           and A.id_inversion = I.id_inversion
		   and (A.id_estado_amortizacion IN (134, 135, 136) OR I.fecha_venta IS NULL)
       GROUP BY anio 
       ORDER BY anio ASC;
       
       
   END IF;

END$$

DROP PROCEDURE IF EXISTS `SP_VENTA_PARTE_PAPEL_COMERCIAL_DESA`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_VENTA_PARTE_PAPEL_COMERCIAL_DESA` (IN `_valorNominalOriginal` DECIMAL(8,2), IN `_valorNominalVendido` DECIMAL(8,2), IN `_fechaCompra` DATE, IN `_propietario` INT)   BEGIN
/*
SE DEBE USAR EL SISTEMA ESTE SP DEBE SER DEPRECADO
SET @valorNominalRestante :=  _valorNominalOriginal-_valorNominalVendido;

select @inv_id := id_inversion from sipro_desa.inversion where fecha_compra=_fechaCompra and valor_nominal = _valorNominalOriginal and id_propietario=1;

select @inv_id;

update sipro_desa.inversion SET 
     valor_nominal = valor_nominal * (@valorNominalRestante / _valorNominalOriginal),
     monto_a_negociar = monto_a_negociar * (@valorNominalRestante / _valorNominalOriginal),
     capital_invertido = capital_invertido * (@valorNominalRestante / _valorNominalOriginal),
     valor_efectivo = valor_efectivo * (@valorNominalRestante / _valorNominalOriginal),
     -- valor_interes = valor_interes * (@valorNominalRestante / _valorNominalOriginal),
     interes_primer_mes = interes_primer_mes * (@valorNominalRestante / _valorNominalOriginal),
     comision_bolsa = comision_bolsa * (@valorNominalRestante / _valorNominalOriginal),
     comision_casa_valores = comision_casa_valores * (@valorNominalRestante / _valorNominalOriginal),
     retencion_fuente = retencion_fuente * (@valorNominalRestante / _valorNominalOriginal),
     
     valor_sin_comision = valor_sin_comision * (@valorNominalRestante / _valorNominalOriginal),
     valor_con_interes = valor_con_interes * (@valorNominalRestante / _valorNominalOriginal),
     interes_acumulado_previo = interes_acumulado_previo * (@valorNominalRestante / _valorNominalOriginal),
     total_comisiones = total_comisiones * (@valorNominalRestante / _valorNominalOriginal)
WHERE id_inversion = @inv_id;



-- select * from amortizacion where inv_id = @inv_id order by id desc;
UPDATE sipro_desa.amortizacion SET
     interes = round(interes * (@valorNominalRestante / _valorNominalOriginal),2),
     capital = round(capital * (@valorNominalRestante / _valorNominalOriginal),2),
     descuento = round(descuento * (@valorNominalRestante / _valorNominalOriginal),2),
     int_parcial = round(int_parcial * (@valorNominalRestante / _valorNominalOriginal),2),
     total = round(total * (@valorNominalRestante / _valorNominalOriginal),2),
     retencion = round(retencion * (@valorNominalRestante / _valorNominalOriginal),2)
WHERE fecha_pago >= curdate()
and id_estado_amortizacion IN (134, 136)
and id_inversion = @inv_id;
*/
END$$

DELIMITER ;

