  `CREATION_DATE` datetime NOT NULL DEFAULT '2019-03-08 00:00:00' COMMENT 'Fecha de creacion',
  `CREATOR` varchar(10) CHARACTER SET utf8 COLLATE utf8_spanish_ci NOT NULL DEFAULT 'Jhon' COMMENT 'Creador',
  `LASTKEY_DATE` datetime NOT NULL DEFAULT '2019-03-08 00:00:00' COMMENT 'Fecha ultima actualizacion',
